import re
import sys
from pathlib import Path

# 低于 min 的物品及应补货量 = min - qty（stock.csv: 苹果 3/5 -> 2，牛奶 1/4 -> 3）
LOW = {"苹果": "2", "牛奶": "3"}
# 未低于 min 的物品，不应出现（香蕉 10/4，面包 6/2）
OK = ["香蕉", "面包"]

p = Path("restock.md")
if not p.exists():
    sys.exit("restock.md 不存在")
text = p.read_text(encoding="utf-8")
lines = text.splitlines()

for name, shortfall in LOW.items():
    matched = [l for l in lines if name in l]
    if not matched:
        sys.exit(f"缺少 {name}")
    if not any(shortfall in re.findall(r"\d+", l) for l in matched):
        sys.exit(f"{name} 所在行缺少应补货量 {shortfall}")

for name in OK:
    if name in text:
        sys.exit(f"不应包含 {name}")

print("restock 检查通过")
